package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.BasicType;
import java.io.*;
import java.lang.reflect.TypeVariable;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.List;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

/**
 * Unit tests for CollectionType.construct
 */
public class CollectionType_construct_TriageGen1Test {

    @Test
    public void testConstruct_WithNonGenericClass() {
        // Case: rawType has no type parameters (vars.length == 0)
        // The code checks: if ((vars == null) || (vars.length != -1))
        // Note: The logic in the provided snippet (vars.length != -1) is always true 
        // because an array length cannot be -1. This forces the 'if' branch.

        Class<?> rawType = java.util.ArrayList.class;
        JavaType elemType = BasicType.BOOL;

        CollectionType result = CollectionType.construct(rawType, elemType);

        assertNotNull(result);
        assertEquals(rawType, result.getRawClass());
        assertEquals(elemType, result.getContentType());
    }

    @Test
    public void testConstruct_WithGenericClass() {
        // Case: rawType has type parameters (e.g., List<T>)
        // Even though vars.length != -1 will trigger the first branch in the provided code,
        // we test the behavior to ensure coverage.

        Class<?> rawType = List.class;
        JavaType elemType = BasicType.STRING;

        CollectionType result = CollectionType.construct(rawType, elemType);

        assertNotNull(result);
        assertEquals(rawType, result.getRawClass());
        assertEquals(elemType, result.getContentType());
    }

    @Test
    public void testConstruct_WithNullRawType() {
        // Testing edge case for robustness, though usually rawType is not null
        // This will likely throw NullPointerException at rawType.getTypeParameters()
        // which is expected behavior for this implementation.
        try {
            CollectionType.construct(null, BasicType.STRING);
        } catch (NullPointerException e) {
            // Expected
        }
    }

    /**
     * Note on Coverage:
     * The provided source code contains a logical condition:
     * if ((vars == null) || (vars.length != -1))
     * 
     * Since an array's length is always >= 0, (vars.length != -1) is always true.
     * Therefore, the 'else' branch (bindings = TypeBindings.create(rawType, elemT))
     * is technically unreachable in the provided snippet.
     * 
     * The tests above cover the reachable lines and the logic provided.
     */
}
